@use 'abstracts' as *;


.l-header {
  transition: $transition;
  position: sticky;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 100;

  &__container {
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  &--pinned {
    transform: translateY(0%);
    background: $base-background-colour;
  }

  &.header--not-top {
    background: $base-background-colour;

    .l-header__branding {
      img {
        max-width: 150px;
      }
    }
  }

  &--top {
    background: transparent;
  }

  &--unpinned {
    transform: translateY(-150%);
  }

  &__branding {
    display: flex;

    img {
      transition: $transition;
    }
  }

  &__menu {
    display: none;
    
    @include media($breakpoint-md, min) {
        display: flex;
    }
    
    ul {
        display: flex;
        gap: 3rem;

        li {
            position: relative;
            &.menu-item-has-children {
                a {
                    display: flex;
                    align-items: center;
                    gap: .4rem;
                }
            }

            ul {
                position: absolute;
                display: none;
                flex-direction: column;
                background-color: $white;
                gap: 0;
                left: -2rem;
                // box-shadow: $shadow;

                li {
                    a {
                        padding: .3rem 2rem;
                        text-wrap: nowrap;
                        display: block;
                        border-bottom: 1px solid rgba($gray-1, 0.9);

                        &:hover {
                            background-color: $gray-1;
                        }
                    }

                    &:last-child {
                        a {
                            border-bottom: none;
                        }
                    }
                }
            }
        }
    }
  }
}

.c-promotion-bar { background: $rudnik-green; color: $white; font-size: 1.4rem; font-weight: 700; }
.c-promotion-bar__inner { align-items: center; display: flex; justify-content: center; min-height: 34px; }
.l-header {
  background: $white;
  &__utility, &__primary { align-items: center; display: flex; justify-content: space-between; }
  &__utility { gap: 20px; min-height: 56px; font-size: 1.4rem; }
  &__primary { border-top: 1px solid #ececec; min-height: 79px; }
  &__contact, &__actions { align-items: center; display: flex; gap: 20px; white-space: nowrap; }
  &__contact span:last-child { color: $rudnik-green; font-weight: 700; }
  &__search { border: 1px solid #ddd; border-radius: 22px; display: flex; flex: 1 1 338px; max-width: 400px; overflow: hidden; }
  &__search input { border: 0; font: inherit; min-width: 0; padding: 10px 16px; width: 100%; }
  &__search button { background: transparent; border: 0; padding: 10px; width: 42px; }
  &__search img, &__action img { display: block; max-height: 22px; max-width: 22px; }
  &__secondary-nav ul { display: flex; font-weight: 700; gap: 26px; white-space: nowrap; }
  &__secondary-nav a { color: $black; }
}
@media (max-width: $breakpoint-lg) { .l-header__secondary-nav { display: none; } }
@media (max-width: $breakpoint-md) { .l-header__utility { display: none; } .l-header__primary { min-height: 64px; } }
@use 'abstracts' as *;

.l-footer {
    &__container {
        
    }
}

.l-footer { background: linear-gradient(135deg, $rudnik-green-dark, $rudnik-green); color: $white; padding: 40px 0 24px;
  &__panel { background: $black; border-radius: 24px; padding: 40px 9.5%; }
  &__grid { display: grid; gap: 42px; grid-template-columns: 2.4fr repeat(3, 1fr); }
  &__logo img { margin-bottom: 20px; width: 165px; }
  &__contact p, &__column p { font-size: 1.4rem; line-height: 1.4; margin: 0 0 10px; }
  &__contact p:first-of-type, &__column h2, &__awards h2 { font-size: 1.6rem; font-weight: 700; margin: 0 0 12px; }
  &__social img { height: 32px; margin-top: 8px; width: 32px; }
  &__awards { align-items: end; display: flex; gap: 20px; grid-column: 3 / span 2; }
  &__awards h2 { max-width: 130px; }
  &__awards > div { align-items: center; display: flex; gap: 10px; }
  &__awards img { max-height: 38px; max-width: 44px; object-fit: contain; }
  &__legal { border-top: 1px solid #777; font-size: 1.3rem; font-weight: 700; line-height: 1.45; margin: 28px 0 0; padding-top: 18px; }
  &__bottom { display: flex; font-size: 1.2rem; justify-content: space-between; padding-top: 18px; }
}
@media (max-width: $breakpoint-md) { .l-footer__grid { grid-template-columns: 1fr 1fr; } .l-footer__awards { grid-column: auto; } }
@media (max-width: $breakpoint-sm) { .l-footer__panel { padding: 30px 24px; } .l-footer__grid { grid-template-columns: 1fr; } .l-footer__awards { align-items: start; grid-column: auto; } .l-footer__bottom { flex-direction: column; gap: 12px; } }
@use 'abstracts' as *;


.wpcf7 {
    .screen-reader-response {
        display: none;
    }

    form {
        color: $white;
        display: flex;
        flex-direction: column;
        gap: 6rem;

        textarea {
            // height: 200px;
        }

        .row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 1.6rem;

            @include media($breakpoint-sm) {
                grid-template-columns: 1fr;
                textarea {
                    height: 150px;
                }
            }

            

            &.full {
                grid-template-columns: 1fr;

            }

            .col {
                height: 100%;

                p {
                    display: flex;
                    flex-direction: column;
                    justify-content: space-between;
                    height: 100%;

                    gap: 1.6rem;

                    br {
                        display: none;
                    }
                    span {
                        display: block;
                    }
                }
            }

            &.privacy {
                font-size: 1.6rem;
                line-height: 2.4rem;
                color: $gray-1;

                a {
                    color: $white;

                    &:hover {
                        color: $accent;
                    }
                }

                label {
                    display: flex;
                    gap: 1rem;

                    @include media($breakpoint-sm) {
                        font-size: 1.4rem;
                    }
                }
            }

            &.submit {
                display: flex;
                justify-content: center;
            }
        }

        .wpcf7-response-output {
            width: fit-content;
            margin: 0 auto;
            border-radius: 5px;
            font-size: 14px;
            line-height: 1;
            padding: 1rem 3rem;
        }

        &.invalid {
            .wpcf7-response-output {
                background-color: rgba($error-colour, .9);
                border: 1px solid $error-colour;
                
            }
        }
        &.sent {
            .wpcf7-response-output {
                background-color: rgba($success-colour, .9);
                border: 1px solid $success-colour;
                
            }
        }
        &.unaccepted {
            .wpcf7-response-output {
                background-color: rgba($warning-colour, .9);
                border: 1px solid $warning-colour;
                
            }

            input[type="checkbox"] {
                border: 1px solid rgba($error-colour, 1);
            }
        }
    }

    .wpcf7-form-control-wrap {
        position: relative;
        .wpcf7-not-valid-tip {
            position: absolute;
            left: -.2rem;
            bottom: -1.6rem;
            background-color: rgba($error-colour, .9);
            border: 1px solid $error-colour;
            border-radius: 5px;
            font-size: 12px;
            line-height: 1;
            padding: .4rem;

        }
    }

    
}
@use 'abstracts' as *;

.c-careers-banner {
  background-color: #006633;
  background-image: linear-gradient(90deg, rgba(0, 102, 51, .8), rgba(0, 102, 51, 0)), var(--careers-banner-image);
  background-position: center;
  background-size: cover;
  color: $white;
  min-height: 220px;

  &__inner { align-items: center; display: flex; flex-direction: column; justify-content: center; min-height: 220px; }
  &__breadcrumb { font-size: 14px; margin: 0 0 18px; }
  h1 { font-size: 48px; font-weight: 700; line-height: 1; margin: 0; }
}

.c-careers-vacancies { margin: 0 auto; max-width: 1196px; }
.c-careers-vacancies__list { display: grid; gap: 20px; }

.c-career-vacancy {
  background: #f6f6f6;
  border: 1px solid #c8c8c8;
  border-radius: 30px;
  overflow: hidden;

  summary { align-items: center; background: #006633; color: $white; cursor: pointer; display: flex; font-size: 24px; font-weight: 700; justify-content: space-between; list-style: none; min-height: 114px; padding: 30px 40px; }
  summary::-webkit-details-marker { display: none; }
  &__icon { border: solid currentColor; border-width: 0 2px 2px 0; height: 12px; transform: rotate(45deg); transition: transform .2s ease; width: 12px; }
  &[open] .c-career-vacancy__icon { transform: rotate(225deg); }
  &__body { padding: 45px 100px 58px; }
  &__description { color: #11111b; font-size: 18px; line-height: 1.4; }
  &__description p { margin: 0 0 24px; }
  &__description ul { margin: -8px 0 24px; padding-left: 20px; }
  &__description li { margin: 0 0 3px; }
}

.c-career-application {
  margin-top: 36px;
  .wpcf7 { color: #11111b; }
  .wpcf7 form { display: grid; gap: 26px; }
  .wpcf7 p { margin: 0; }
  .wpcf7 label { display: block; font-size: 18px; }
  .wpcf7-form-control-wrap { display: block; margin-top: 8px; }
  input:not([type='checkbox']):not([type='submit']) { background: $white; border: 1px solid #c8c8c8; border-radius: 15px; font: inherit; height: 62px; padding: 0 20px; width: 100%; }
  .c-careers-form__contact { display: grid; gap: 20px; grid-template-columns: repeat(2, 1fr); }
  .c-careers-form__contact > p:first-child { grid-column: 1 / -1; }
  .c-careers-form__upload { align-items: center; display: flex; gap: 18px; }
  input[type='file'] { font-size: 14px; max-width: 223px; }
  .c-careers-form__consents { display: grid; font-size: 14px; gap: 12px; line-height: 1.35; }
  .c-careers-form__consents label { align-items: flex-start; display: flex; font-size: inherit; gap: 10px; }
  .c-careers-form__consents input { accent-color: #056839; margin-top: 3px; }
  input[type='submit'] { background: #056839; border: 0; border-radius: 30px; color: $white; font: inherit; font-weight: 700; justify-self: end; min-height: 44px; min-width: 221px; padding: 0 30px; }
}

.c-careers-cta { background: #006633 var(--careers-cta-background) center / cover no-repeat; color: $white; margin: 52px 36px 0; min-height: 230px; }
.c-careers-cta__inner { align-items: center; display: flex; gap: 50px; justify-content: center; margin: 0 auto; min-height: 230px; padding: 30px; text-align: center; }
.c-careers-cta h2 { font-size: 48px; font-weight: 700; line-height: 1.1; margin: 0; }
.c-careers-cta__button { border: 1px solid $white; border-radius: 30px; color: $white; font-weight: 700; padding: 12px 30px; text-decoration: none; white-space: nowrap; }

@include media($breakpoint-md) {
  .c-careers-vacancies { margin-inline: 20px; }
  .c-career-vacancy__body { padding-inline: 40px; }
  .c-careers-cta { margin-inline: 20px; }
  .c-careers-cta h2 { font-size: 36px; }
}

@include media($breakpoint-sm) {
  .c-careers-banner, .c-careers-banner__inner { min-height: 180px; }
  .c-careers-banner h1 { font-size: 38px; }
  .c-career-vacancy summary { font-size: 19px; min-height: 86px; padding: 22px 25px; }
  .c-career-vacancy__body { padding: 30px 25px; }
  .c-career-application .c-careers-form__contact { grid-template-columns: 1fr; }
  .c-career-application .c-careers-form__contact > p:first-child { grid-column: auto; }
  .c-career-application input[type='submit'] { justify-self: start; }
  .c-careers-cta { margin-inline: 0; }
  .c-careers-cta__inner { flex-direction: column; gap: 24px; }
  .c-careers-cta h2 { font-size: 30px; }
}

